#!/usr/bin/env python3
"""Build the shipment summary described in /app/docs/summary-format.md."""
import csv
import datetime as dt
import gzip
import json
import os
import re
import sys
import xml.etree.ElementTree as ET
from decimal import Decimal, ROUND_HALF_UP

FACTORS = {
    "kg": Decimal(1),
    "g": Decimal("0.001"),
    "lb": Decimal("0.45359237"),
    "oz": Decimal("0.028349523125"),
}
ORDER = ["central", "south", "east", "river", "north", "west", "harbor", "lakeside"]
UNITS = set(FACTORS)
MONTHS = {m: i + 1 for i, m in enumerate(
    "jan feb mar apr may jun jul aug sep oct nov dec".split())}

COLS = {
    "east": ["id", "type", "shipped", "gross", "net", "status", "note"],
    "lakeside": ["id", "kind", "booked", "shipped", "gross_kg", "net_kg", "status"],
    "river": ["t", "ref", "shipped", "weight", "status"],
    "west": ["id", "typ", "shipped", "weight", "status", "note"],
    "harbor": ["rec", "ref", "date", "weight", "state"],
}
DELIM = {"east": ",", "lakeside": ",", "river": "\t", "west": ";", "harbor": "|"}
ID_RE = re.compile(r"^\s*SH\D*?(\d+)\s*$", re.I)

HARBOR_STATE = {"DLV": "delivered", "DLL": "delivered_late", "CAN": "cancelled",
                "RET": "returned", "HLD": "held"}
FW_STATUS = {"D": "delivered", "L": "delivered_late", "C": "cancelled",
             "R": "returned", "H": "held"}


# ---------------------------------------------------------------- bytes/text
def read_bytes(path):
    with open(path, "rb") as fh:
        b = fh.read()
    if b[:2] == b"\x1f\x8b":
        b = gzip.decompress(b)
    return b


def decode(b):
    if b.startswith(b"\xef\xbb\xbf"):
        return b[3:].decode("utf-8")
    if b.startswith(b"\xff\xfe") or b.startswith(b"\xfe\xff"):
        return b.decode("utf-16")
    m = re.search(rb"^#\s*charset\s*:\s*([A-Za-z0-9_.:-]+)", b[:2000], re.M | re.I)
    enc = m.group(1).decode("ascii") if m else "utf-8"
    try:
        return b.decode(enc)
    except (LookupError, UnicodeDecodeError):
        return b.decode("utf-8", errors="replace")


# -------------------------------------------------------------------- values
def norm_id(s):
    m = ID_RE.match(s or "")
    return int(m.group(1)) if m else None


def norm_status(s):
    return re.sub(r"[\s\-]+", "_", (s or "").strip().lower())


def parse_unit(s):
    for t in re.findall(r"[A-Za-z]+", s or ""):
        if t.lower() in UNITS:
            return t.lower()
    return None


def parse_number(s, style):
    s = s.strip()
    if style == "eu":
        s = s.replace(".", "").replace(",", ".")
    else:
        s = s.replace(",", "")
    return Decimal(s)


def parse_weight(text, unit, style):
    """text may carry its own unit suffix; returns kg Decimal or None."""
    text = (text or "").strip()
    if not text:
        return None
    m = re.match(r"^(.*?)\s*([A-Za-z]+)$", text)
    if m and m.group(2).lower() in UNITS:
        text, unit = m.group(1), m.group(2).lower()
    try:
        v = parse_number(text, style)
    except Exception:
        return None
    return v * FACTORS[unit or "kg"]


def serial_date(n):
    return dt.date(1899, 12, 31) + dt.timedelta(days=int(Decimal(n)))


def parse_date(v, form):
    """Return 'YYYY-MM' or None."""
    v = (v or "").strip()
    if not v:
        return None
    form = (form or "").strip()
    fl = form.lower()
    m = re.match(r"^(\d{4})-(\d\d)-(\d\d)[T ](\d\d):(\d\d)(?::(\d\d)(?:\.\d+)?)?\s*(Z|[+-]\d\d:?\d\d)?$", v)
    if m:
        return iso_utc(v)
    try:
        if fl == "serial" or (re.fullmatch(r"\d{5}(\.\d+)?", v) and fl not in ("yyyymmdd",)):
            d = serial_date(v)
        elif fl in ("dmy", "dd/mm/yyyy", "dd.mm.yyyy"):
            a, b, c = re.split(r"[-/.]", v)
            d = dt.date(int(c), int(b), int(a))
        elif fl in ("mdy", "mm/dd/yyyy"):
            a, b, c = re.split(r"[-/.]", v)
            d = dt.date(int(c), int(a), int(b))
        else:  # iso / YMD
            a, b, c = re.split(r"[-/.]", v)
            d = dt.date(int(a), int(b), int(c))
    except Exception:
        return None
    return "%04d-%02d" % (d.year, d.month)


def iso_utc(v):
    v = v.strip()
    try:
        s = v.replace("Z", "+00:00").replace("z", "+00:00")
        s = re.sub(r"([+-]\d\d)(\d\d)$", r"\1:\2", s)
        d = dt.datetime.fromisoformat(s)
        if d.tzinfo is not None:
            d = d.astimezone(dt.timezone.utc)
        return "%04d-%02d" % (d.year, d.month)
    except Exception:
        m = re.match(r"(\d{4})-(\d\d)", v)
        return m.group(0) if m else None


def rec(num, typ, month, kg, status):
    return {"num": num, "type": typ, "month": month, "kg": kg, "status": status}


TYPES = {"": "new", "N": "new", "NEW": "new", "C": "corr", "COR": "corr",
         "CORR": "corr", "CORRECTION": "corr", "AMEND": "corr",
         "V": "void", "VOID": "void"}


def rtype(s):
    return TYPES.get((s or "").strip().upper(), "new")


# ------------------------------------------------------------------- parsers
def parse_delimited(depot, text):
    d = DELIM[depot]
    names = set(COLS[depot])
    quoting = depot in ("east", "lakeside")
    seq = None
    directives = {}
    header = None
    out = []
    lines = text.replace("\r\n", "\n").replace("\r", "\n").split("\n")
    i = 0
    hm = re.match(r"^#.*seq=(\d+)", lines[0]) if lines else None
    if hm:
        seq = int(hm.group(1))
    while i < len(lines):
        line = lines[i]
        i += 1
        if line.startswith("\ufeff"):
            line = line[1:]
        if line.startswith("#"):
            m = re.match(r"^#\s*([^:=]+?)\s*:\s*(.*?)\s*$", line)
            if m:
                name = m.group(1).strip().lower()
                directives[name] = m.group(2)
                if name == "seq" and seq is None:
                    try:
                        seq = int(m.group(2))
                    except ValueError:
                        pass
            else:
                m = re.search(r"seq=(\d+)", line)
                if m and seq is None:
                    seq = int(m.group(1))
            continue
        if not line.strip():
            continue
        if quoting:
            while line.count('"') % 2 and i < len(lines):
                line += "\n" + lines[i]
                i += 1
            row = next(csv.reader([line], delimiter=d))
        else:
            row = line.split(d)
        fields = [f.strip() for f in row]
        if fields and all(f in names for f in fields):
            header = fields
            continue
        if header is None:
            continue
        rowunit = None
        if len(row) > len(header):
            idx = [k for k, f in enumerate(fields) if f.lower() in UNITS]
            wcol = next((k for k, h in enumerate(header)
                         if h in ("gross", "weight", "gross_kg")), None)
            pick = None
            if wcol is not None and wcol + 1 < len(fields) and fields[wcol + 1].lower() in UNITS:
                pick = wcol + 1
            elif idx:
                pick = idx[0]
            if pick is not None:
                rowunit = fields[pick].lower()
                del row[pick]
            # wcol shifts are handled because we deleted the field itself
            if len(row) > len(header) and not quoting:
                row = row[:len(header) - 1] + [d.join(row[len(header) - 1:])]
        if len(row) < len(header):
            row = list(row) + [""] * (len(header) - len(row))
        r = {h: v.strip() for h, v in zip(header, row)}
        idcol = "id" if "id" in r else "ref"
        num = norm_id(r.get(idcol))
        if num is None:
            continue
        out.append((num, r, rowunit, dict(directives)))
    recs = []
    for num, r, rowunit, dirs in out:
        recs.append(build_delim(depot, num, r, rowunit, dirs))
    return seq, recs


def build_delim(depot, num, r, rowunit, dirs):
    if depot == "harbor":
        typ = rtype(r.get("rec"))
        if typ == "void":
            return rec(num, typ, None, None, None)
        month = parse_date(r.get("date"), dirs.get("dates") or dirs.get("date format") or "iso")
        kg = parse_weight(r.get("weight"), parse_unit(dirs.get("weight unit") or dirs.get("unit")) or "kg", "us")
        st = HARBOR_STATE.get(r.get("state", "").strip().upper(), norm_status(r.get("state")))
        return rec(num, typ, month, kg, st)
    if depot == "east":
        typ = rtype(r.get("type"))
        if typ == "void":
            return rec(num, typ, None, None, None)
        month = parse_date(r.get("shipped"), dirs.get("dates") or "YMD")
        unit = rowunit or parse_unit(dirs.get("unit")) or parse_unit(dirs.get("weight unit")) or "kg"
        kg = parse_weight(r.get("gross"), unit, "us")
        return rec(num, typ, month, kg, norm_status(r.get("status")))
    if depot == "lakeside":
        typ = rtype(r.get("kind"))
        if typ == "void":
            return rec(num, typ, None, None, None)
        month = parse_date(r.get("shipped"), dirs.get("dates") or "iso")
        kg = parse_weight(r.get("gross_kg"), "kg", "us")
        return rec(num, typ, month, kg, norm_status(r.get("status")))
    if depot == "river":
        typ = rtype(r.get("t"))
        if typ == "void":
            return rec(num, typ, None, None, None)
        month = parse_date(r.get("shipped"), dirs.get("date format") or dirs.get("dates") or "MM/DD/YYYY")
        unit = rowunit or parse_unit(dirs.get("weight unit")) or parse_unit(dirs.get("unit")) or "kg"
        kg = parse_weight(r.get("weight"), unit, "us")
        return rec(num, typ, month, kg, norm_status(r.get("status")))
    # west
    typ = rtype(r.get("typ"))
    if typ == "void":
        return rec(num, typ, None, None, None)
    month = parse_date(r.get("shipped"), "DD.MM.YYYY")
    unit = rowunit or parse_unit(dirs.get("weight unit")) or parse_unit(dirs.get("unit")) or "kg"
    kg = parse_weight(r.get("weight"), unit, "eu")
    return rec(num, typ, month, kg, norm_status(r.get("status")))


def parse_north(text):
    seq = None
    recs = []

    def handle(o):
        nonlocal seq
        if not isinstance(o, dict):
            return
        if "meta" in o and isinstance(o["meta"], dict):
            if seq is None and o["meta"].get("seq") is not None:
                seq = int(o["meta"]["seq"])
            return
        num = norm_id(str(o.get("id", "")))
        if num is None:
            return
        typ = rtype(o.get("kind"))
        if typ == "void":
            recs.append(rec(num, typ, None, None, None))
            return
        kg = None
        for k, v in o.items():
            m = re.match(r"^weight_(kg|g|lb|oz)$", k, re.I)
            if m and v is not None:
                kg = parse_weight(str(v), m.group(1).lower(), "us")
        recs.append(rec(num, typ, iso_utc(str(o.get("shipped_at", ""))),
                        kg, norm_status(o.get("status"))))

    for line in text.split("\n"):
        line = line.strip()
        if not line:
            continue
        try:
            v = json.loads(line, parse_float=Decimal, parse_int=Decimal)
        except ValueError:
            continue
        if isinstance(v, list):
            for o in v:
                handle(o)
        else:
            handle(v)
    return seq, recs


def parse_central(b):
    root = ET.fromstring(b)
    seq = int(root.get("seq")) if root.get("seq") else None
    base = (root.get("weight-unit") or "kg").lower()
    recs = []

    def get(el, name):
        c = el.find(name)
        if c is not None:
            return c
        return None

    for el in root.iter("shipment"):
        num = norm_id(el.get("id"))
        if num is None:
            continue
        typ = rtype({"correction": "C", "void": "V"}.get((el.get("type") or "").lower(), "N"))
        if typ == "void":
            recs.append(rec(num, typ, None, None, None))
            continue
        w = get(el, "weight")
        unit = None
        if w is not None:
            wt = (w.text or "").strip()
            unit = (w.get("unit") or "").lower() or None
        else:
            wt = (el.get("weight") or "").strip()
        unit = unit if unit in UNITS else (el.get("weight-unit") or base).lower()
        kg = parse_weight(wt, unit, "us")
        sh = get(el, "shipped")
        sv = (sh.text or "").strip() if sh is not None else (el.get("shipped") or "").strip()
        month = None
        if re.match(r"^\d{1,2}\s+[A-Za-z]{3}[A-Za-z]*\.?\s+\d{4}$", sv):
            d, mo, y = sv.split()
            month = "%04d-%02d" % (int(y), MONTHS[mo[:3].lower()])
        elif "T" in sv or " " in sv:
            month = iso_utc(sv.replace(" ", "T"))
        else:
            month = parse_date(sv, "iso")
        st = get(el, "status")
        st = (st.text or "") if st is not None else (el.get("status") or "")
        recs.append(rec(num, typ, month, kg, norm_status(st)))
    return seq, recs


FW = {
    "FW1": (42, {"id": (0, 9), "type": (9, 10), "date": (10, 17), "w": (17, 25), "st": (25, 26)}, "yd", Decimal("1"), "g"),
    "FW2": (43, {"type": (0, 1), "id": (1, 10), "date": (10, 18), "w": (18, 26), "st": (26, 27)}, "ymd", Decimal("0.01"), "kg"),
    "FW3": (41, {"id": (0, 9), "date": (9, 16), "type": (16, 17), "w": (17, 24), "st": (24, 25)}, "yd", Decimal("0.1"), "lb"),
}


def parse_south(text):
    seq = None
    layout = None
    recs = []
    bylen = {v[0]: k for k, v in FW.items()}
    for line in text.replace("\r\n", "\n").replace("\r", "\n").split("\n"):
        if "\x0c" in line:
            continue
        if line.startswith("#"):
            m = re.match(r"^#LAYOUT\s+(\S+)", line)
            if m:
                layout = m.group(1).upper()
            m = re.match(r"^#SEQ\s+(\d+)", line)
            if m and seq is None:
                seq = int(m.group(1))
            continue
        if not line.strip():
            continue
        lay = bylen.get(len(line))
        if lay is None:
            lay = layout
            if lay not in FW:
                continue
            line = line.ljust(FW[lay][0])
        length, pos, dform, scale, unit = FW[lay]
        g = {k: line[a:b] for k, (a, b) in pos.items()}
        num = norm_id(g["id"])
        if num is None:
            continue
        typ = rtype(g["type"])
        if typ == "void":
            recs.append(rec(num, typ, None, None, None))
            continue
        try:
            if dform == "yd":
                y, doy = int(g["date"][:4]), int(g["date"][4:])
                d = dt.date(y, 1, 1) + dt.timedelta(days=doy - 1)
            else:
                d = dt.date(int(g["date"][:4]), int(g["date"][4:6]), int(g["date"][6:8]))
            month = "%04d-%02d" % (d.year, d.month)
        except Exception:
            month = None
        try:
            kg = Decimal(int(g["w"])) * scale * FACTORS[unit]
        except Exception:
            kg = None
        recs.append(rec(num, typ, month, kg, FW_STATUS.get(g["st"].strip().upper(), "")))
    return seq, recs


# ---------------------------------------------------------------------- main
def parse_file(depot, path):
    b = read_bytes(path)
    if depot == "central":
        return parse_central(b)
    text = decode(b)
    if depot == "north":
        return parse_north(text)
    if depot == "south":
        return parse_south(text)
    if depot in DELIM:
        return parse_delimited(depot, text)
    # unknown depot: guess by content
    s = text.lstrip()
    if s.startswith("<"):
        return parse_central(b)
    if s.startswith("{") or s.startswith("["):
        return parse_north(text)
    return None, []


def main(data_dir, out_file):
    exports = {}
    for name in sorted(os.listdir(data_dir)):
        p = os.path.join(data_dir, name)
        if not os.path.isfile(p):
            continue
        depot = name.split("-", 1)[0]
        seq, recs = parse_file(depot, p)
        exports.setdefault(depot, []).append((seq if seq is not None else -1, name, recs))

    corrections = resends = 0
    current = {}
    for depot, lst in exports.items():
        lst.sort(key=lambda t: (t[0], t[1]))
        cur = {}
        for _, _, recs in lst:
            for r in recs:
                n = r["num"]
                if r["type"] == "new":
                    if n in cur:
                        resends += 1
                    else:
                        cur[n] = r
                elif r["type"] == "corr":
                    cur[n] = r
                    corrections += 1
                else:
                    cur.pop(n, None)
                    corrections += 1
        current[depot] = cur

    rank = {d: i for i, d in enumerate(ORDER)}
    owners = {}
    for depot, cur in current.items():
        for n in cur:
            owners.setdefault(n, []).append(depot)
    handovers = sum(1 for v in owners.values() if len(v) > 1)

    dep_out = {d: [0, Decimal(0)] for d in sorted(exports)}
    months = {}
    for n, ds in owners.items():
        d = min(ds, key=lambda x: (rank.get(x, 99), x))
        r = current[d][n]
        if r["status"] not in ("delivered", "delivered_late") or r["kg"] is None:
            continue
        dep_out[d][0] += 1
        dep_out[d][1] += r["kg"]
        if r["month"]:
            m = months.setdefault(r["month"], [0, Decimal(0)])
            m[0] += 1
            m[1] += r["kg"]

    def q(x):
        return float(x.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))

